import {readCompressedJSON,decodeSourceBuffer} from './source-data.js';
import {COMPILED_MAP_IDS} from './compiled-map-manifest.js';
export const COMPILED_MAPS=new Set(COMPILED_MAP_IDS);
const hex=a=>Array.from(new Uint8Array(a),v=>v.toString(16).padStart(2,'0')).join('');
async function hash(a){return hex(await crypto.subtle.digest('SHA-256',new Uint8Array(a.buffer,a.byteOffset,a.byteLength)));}
export async function loadCompiledClusters(url,chunks){
 const id=/\/([^/]+)-render\.json\.gz$/.exec(url.pathname)?.[1];if(!COMPILED_MAPS.has(id))return false;
 const data=await readCompressedJSON(new URL('./'+id+'-clusters.json.gz',url));if(data.version!==1||data.source!==chunks.sourceHash||data.artProfile!==chunks.artProfile||data.chunks.length!==chunks.length)throw Error('Compiled map identity mismatch: '+id);
 await Promise.all(data.chunks.map(async(part,i)=>{const c=chunks[i];if(part.family!==c.family||part.positionHash!==await hash(c.attributes.position.array)||part.indexHash!==await hash(c.index.array))throw Error('Compiled map geometry mismatch: '+id);for(const [key,a]of Object.entries(c.attributes))if(part.attributeHashes?.[key]!==await hash(a.array))throw Error('Compiled map attribute mismatch: '+id);if(/^(glass|fence|light)(@|~|$)/.test(c.family))return;const axes=decodeSourceBuffer(part.uvAxes,Uint8Array);if(axes.length!==c.attributes.position.array.length/3||axes.some(v=>v>2))throw Error('Invalid compiled UV basis');const corrections=decodeSourceBuffer(part.uvCorrections,Int32Array),offsets=new Int16Array(axes.length*2);if(corrections.length%3)throw Error('Invalid compiled UV corrections');for(let j=0;j<corrections.length;j+=3){const i=corrections[j],u=corrections[j+1],v=corrections[j+2];if(i<0||i>=axes.length||Math.abs(u)>32767||Math.abs(v)>32767)throw Error('Invalid compiled UV correction');offsets[i*2]=u;offsets[i*2+1]=v;}c.uvAxes=axes;c.uvOffsets=offsets;c.projectedUV=part.projectedUV===true;const near=[];
  c.clusters=part.clusters.map(cluster=>{if(cluster.bounds.length!==6||cluster.bounds.some(v=>!Number.isFinite(v)))throw Error('Invalid compiled bounds');const levels=cluster.levels.map((l,j)=>{if(l.reuse!==undefined){if(l.reuse<0||l.reuse>=j)throw Error('Invalid level reference');return {reuse:l.reuse};}const packed=decodeSourceBuffer(l.blob,Int32Array),index=new Uint32Array(packed.length);if(index.length!==l.count||index.length%3||!Number.isFinite(l.error)||l.error<0)throw Error('Invalid compiled level');let previous=0;for(let k=0;k<packed.length;k++){previous+=packed[k];if(previous<0||previous>=c.attributes.position.array.length/3)throw Error('Invalid compiled vertex');index[k]=previous;}return{index,error:l.error};});for(let j=0;j<levels.length;j++)if(levels[j].reuse!==undefined)levels[j]=levels[levels[j].reuse];if(!levels.length||levels[0].error!==0)throw Error('Missing exact near level');near.push(levels[0].index);return{bounds:cluster.bounds,levels};});
  const draw=new Uint32Array(near.reduce((n,a)=>n+a.length,0));let at=0;for(const a of near){draw.set(a,at);at+=a.length;}c.drawIndex=draw;
 }));if(!Array.isArray(data.occluders)||data.occluders.some(t=>t.p.length!==9||t.p.some(v=>!Number.isFinite(v))||!Number.isFinite(t.area)||t.area<=0))throw Error('Invalid compiled occluders');if(data.props){const decode=(level,chunk)=>{const packed=decodeSourceBuffer(level.blob,Int32Array),index=new Uint32Array(packed.length);if(index.length!==level.count||index.length%3||chunk<0||chunk>=chunks.length)throw Error('Invalid prop index layout');let value=0;for(let i=0;i<packed.length;i++){value+=packed[i];if(value<0||value>=chunks[chunk].attributes.position.array.length/3)throw Error('Invalid prop vertex');index[i]=value;}return index;};const additions=chunks.map(()=>[]);chunks.props={stats:data.props.stats,prototypes:data.props.prototypes.map(proto=>{if(typeof proto.closed!=='boolean'||!proto.parts.length||!proto.instances.length)throw Error('Invalid prop prototype');const parts=proto.parts.map(part=>{const levels=[];for(const [i,l]of part.levels.entries()){if(l.reuse!==undefined){if(!Number.isInteger(l.reuse)||l.reuse<0||l.reuse>=i)throw Error('Invalid prop level reference');levels.push(levels[l.reuse]);}else{if(!Number.isFinite(l.error)||l.error<0||i===0&&l.error!==0)throw Error('Invalid prop level');levels.push({index:decode(l,part.chunk),error:l.error});}}return{chunk:part.chunk,levels};});const instances=proto.instances.map(instance=>{if(instance.offset.length!==3||instance.bounds.length!==6||[...instance.offset,...instance.bounds,instance.error].some(x=>!Number.isFinite(x))||instance.error<0||instance.error>.001)throw Error('Invalid prop placement');let count=0;for(const part of instance.sourceParts){const index=decode(part,part.chunk);additions[part.chunk].push(index);count+=index.length;}if(count!==parts.reduce((n,p)=>n+p.levels[0].index.length,0))throw Error('Prop source coverage mismatch');return{offset:instance.offset,bounds:instance.bounds,error:instance.error};});return{closed:proto.closed,parts,instances};})};for(let i=0;i<chunks.length;i++){const c=chunks[i];if(!c.clusters)continue;c.propStaticIndex=c.drawIndex;const lists=[c.drawIndex,...additions[i]],index=new Uint32Array(lists.reduce((n,a)=>n+a.length,0));let at=0;for(const a of lists){index.set(a,at);at+=a.length;}c.drawIndex=index;}}
 chunks.occluders=data.occluders;chunks.compiled=true;chunks.pixelError=data.pixelError;return true;
}
